private void processDegreeInput(EditText degreeText, SeekArc seekArc) {
    String degreeStr = degreeText.getText().toString().trim();

    if (degreeStr.isEmpty()) {
        /* Restore the value of this very servo, taken from its own seek arc.
         * The shared "degree" field must not be used here, since it holds the
         * value last entered for *any* servo and would otherwise leak the
         * value of a different servo into this one. */
        degreeText.setText(String.valueOf((int) (seekArc.getProgress() * 3.6)));
        degreeText.setCursorVisible(false);
        return;
    }

    int enteredDegree;
    try {
        enteredDegree = Integer.parseInt(degreeStr);
    } catch (NumberFormatException e) {
        degreeText.setText(getResources().getString(R.string.zero));
        seekArc.setProgress(0);
        toastInvalidValueMessage();
        return;
    }

    if (enteredDegree > 360 || enteredDegree < 0) {
        degreeText.setText(getResources().getString(R.string.zero));
        seekArc.setProgress(0);
        toastInvalidValueMessage();
    } else {
        degree = enteredDegree;
        seekArc.setProgress((int) (degree / 3.6));
        editEnter = true;
    }
}

